const User = require('./User');  

class UsersList {
    
    constructor() {
        this.users = [];
    }
    getUsers() {
        return this.users;
    }

    addUser(user) {
        this.users.push(user);
    }
}
const usersList = new UsersList();

const user = {
    id: '1',
    firstName: 'John',
    lastName: 'Doe',
    email: 'user1',
    password: 'pass1',
    gender: 'male',
    picture: 'picture.jpg'
};

usersList.addUser(user);

// Export a singleton instance of the UserList class
module.exports = usersList;
